import Foundation

public enum ThemeAssets {
    public static let buranoBase64 = ""
    public static let telegramDoodlesBase64 = ""

    public static let buranoImage: PlatformImage? = {
        guard let data = Data(base64Encoded: buranoBase64) else { return nil }
        return PlatformImage.from(data: data)
    }()

    public static let telegramDoodlesImage: PlatformImage? = {
        guard let data = Data(base64Encoded: telegramDoodlesBase64),
              let img = PlatformImage.from(data: data) else { return nil }
        #if canImport(AppKit)
        img.isTemplate = true
        #endif
        return img
    }()
}